// same shape (the `Dict` type is inferred from `en`), so TypeScript enforces
// that a translation is never forgotten.
//
// This is a curated pilot covering the Settings page and the shared app
// shell (bottom navigation + app header). Pages and strings outside the
// pilot still fall back to English via the `t()` helper.

